function translateUiText(value){const clean=String(value).trim();if(UI_EN[clean])return String(value).replace(clean,UI_EN[clean]);let match=clean.match(/^(\d+) Titel$/);if(match)return `${match[1]} titles`;match=clean.match(/^(\d+) Film(e)?$/);if(match)return `${match[1]} ${match[1]==="1"?"film":"films"}`;match=clean.match(/^Fassung (\d+)$/);if(match)return `Edition ${match[1]}`;return value}
