function filmCollectionNumber(film){const relevant=catalogPlaylistId==="all"?playlists:playlists.filter(playlist=>sameId(playlist.id,catalogPlaylistId));for(const playlist of relevant){const number=playlistNumber(playlist,film.id);if(number)return number}return ""}
function filmMatchesQuery(film,query){const q=String(query||"").trim().toLowerCase();return !q||[film.title,film.originalTitle,film.director,film.cast,film.genre,genreText(film.genre),film.countries,String(film.year),...filmCopies(film).flatMap(copy=>[copy.title||copy.label||"",languageText(copy.languages),languageText(copy.subtitles),copy.resolution,copy.quality])].join(" ").toLowerCase().includes(q)}
function isNeonTheme(){return document.documentElement.dataset.theme==="neon"}
let neonHeaderFrame;
function syncNeonHeader(){cancelAnimationFrame(neonHeaderFrame);neonHeaderFrame=requestAnimationFrame(()=>{const active=currentView==="cinema"&&isNeonTheme(),progress=active?Math.min(Math.max(window.scrollY,0)/360,1):0,mobile=window.innerWidth<=800,maxShrink=mobile?172:239,fade=Math.min(Math.max((progress-.48)/.3,0),1),wasCollapsed=document.documentElement.dataset.headerCollapsed==="true";document.documentElement.style.setProperty("--neon-header-shrink",`${(progress*maxShrink).toFixed(2)}px`);document.documentElement.style.setProperty("--neon-header-offset",`${(-progress*(mobile?150:230)).toFixed(2)}px`);document.documentElement.style.setProperty("--neon-header-scale",(1-progress*.42).toFixed(3));document.documentElement.style.setProperty("--neon-header-brand-opacity",(1-fade).toFixed(3));if(active&&(progress>=.995||wasCollapsed&&progress>.92))document.documentElement.dataset.headerCollapsed="true";else delete document.documentElement.dataset.headerCollapsed})}
