function cover(film,mini=false){const display=localizedFilm(film);return display.cover?`<img class="${mini?"mini-poster":""}" src="${esc(display.cover)}" alt="" onerror="this.remove()">`:mini?`<span class="mini-poster" style="${posterStyle(film)}"></span>`:""}
function render(){const p=activeProject();if(!p)return;els.projectSelect.innerHTML=`<option value="all" ${catalogProjectId==="all"?"selected":""}>Alle Projekte</option>`+projects.map(x=>`<option value="${x.id}" ${x.id===catalogProjectId?"selected":""}>${esc(x.name)}</option>`).join("");els.projectList.innerHTML=projects.map(x=>`<div class="project-row ${x.id===p.id?"is-active":""}" draggable="true" data-project-drag="${x.id}"><button class="project-item" type="button" data-project-id="${x.id}"><span>${esc(x.name)}</span><small>${x.films.length}</small></button><div class="project-row-menu-wrap"><button class="project-row-menu-button" type="button" data-project-row-menu="${x.id}" aria-label="Menü für ${esc(x.name)} öffnen" aria-expanded="false">⋮</button><div class="project-row-menu" data-project-row-popup="${x.id}" hidden><button type="button" data-rename-project="${x.id}">Umbenennen</button><button type="button" data-description-project="${x.id}">Projektbeschreibung</button><button class="project-delete-button" type="button" data-delete-project="${x.id}">Löschen</button></div></div></div>`).join("");els.projectHeading.textContent=catalogProjectId==="all"?"Alle Projekte":projects.find(x=>x.id===catalogProjectId)?.name||"Alle Projekte";els.machineProjectTitle.textContent=p.name;els.projectSummary.textContent=`${p.films.length} ${p.films.length===1?"Film":"Filme"} · ${p.description||"Ohne Beschreibung"}`;renderPlaylists();renderFilters();renderCatalog();renderTable();renderHero()}
function renderPlaylists(){const active=playlists.find(item=>item.id===activePlaylistId);els.playlistList.innerHTML=playlists.map(item=>`<div class="project-row ${item.id===activePlaylistId?"is-active":""}"><button class="project-item" type="button" data-playlist-id="${item.id}"><span>${esc(item.name)}</span><small>${item.filmIds?.length||0}</small></button><div class="project-row-menu-wrap"><button class="project-row-menu-button" type="button" data-playlist-row-menu="${item.id}" aria-label="Menü für ${esc(item.name)} öffnen" aria-expanded="false">⋮</button><div class="project-row-menu" data-playlist-row-popup="${item.id}" hidden><button type="button" data-delete-playlist="${item.id}">Löschen</button></div></div></div>`).join("");els.playlistTitle.textContent=active?.name||"Playlisten";els.playlistSummary.textContent=active?`${active.filmIds?.length||0} ${active.filmIds?.length===1?"Film":"Filme"} · ${active.description||"Ohne Beschreibung"}`:"Noch keine Playlist angelegt.";$("playlistEmptyTitle").textContent=active?"Diese Playlist ist noch leer.":"Filme für einen Abend zusammenstellen";$("playlistEmptyText").textContent=active?"Die Filmzuordnung folgt direkt aus dem Filmarchiv.":"Lege links deine erste Playlist an."}
function setArchiveSection(section){activeArchiveSection=section==="playlists"?"playlists":"projects";document.querySelectorAll("[data-archive-section]").forEach(button=>{const selected=button.dataset.archiveSection===activeArchiveSection;button.classList.toggle("is-active",selected);button.setAttribute("aria-selected",String(selected))});els.projectsSidebarPane.hidden=activeArchiveSection!=="projects";els.playlistsSidebarPane.hidden=activeArchiveSection!=="playlists";els.projectsContent.hidden=activeArchiveSection!=="projects";els.playlistsContent.hidden=activeArchiveSection!=="playlists";closeProjectMenu();closeProjectRowMenus()}
let genresExpanded=false,genreFiltersVisible=true,genreOverflowFrame;
function updateGenreOverflow(){cancelAnimationFrame(genreOverflowFrame);genreOverflowFrame=requestAnimationFrame(()=>{if(!genreFiltersVisible){els.genreToggle.hidden=true;return}const less=interfaceLanguage()==="de"?"Weniger Genres":"Fewer genres",all=interfaceLanguage()==="de"?"Alle Genres":"All genres",more=interfaceLanguage()==="de"?"Mehr Genres":"More genres";els.genreFilters.classList.remove("is-expanded");if(isNeonTheme()){const hasSecondary=Boolean(els.genreFilters.querySelector(".neon-secondary-genre"));els.genreFilters.classList.toggle("is-expanded",genresExpanded&&hasSecondary);els.genreToggle.hidden=!hasSecondary;els.genreToggle.setAttribute("aria-expanded",String(genresExpanded&&hasSecondary));els.genreToggle.innerHTML=genresExpanded&&hasSecondary?`${less} <span aria-hidden="true">⌃</span>`:`${all} <span aria-hidden="true">⌄</span>`;return}const overflowing=els.genreFilters.scrollHeight>els.genreFilters.clientHeight+1;if(genresExpanded&&overflowing)els.genreFilters.classList.add("is-expanded");els.genreToggle.hidden=!overflowing;els.genreToggle.setAttribute("aria-expanded",String(genresExpanded&&overflowing));els.genreToggle.innerHTML=genresExpanded&&overflowing?`${less} <span aria-hidden="true">⌃</span>`:`${more} <span aria-hidden="true">⌄</span>`})}
function setGenreVisibility(visible){genreFiltersVisible=visible;els.genreFilterRegion.classList.toggle("genres-hidden",!visible);els.genreVisibilityToggle.setAttribute("aria-pressed",String(visible));if(!visible){activeGenre="all";genresExpanded=false}saveCatalogState();renderFilters();renderCatalog()}
function renderFilters(){const available=genres(catalogFilms());if(isNeonTheme()){const otherGenres=available.filter(genre=>genre!=="all"&&!NEON_PRIMARY_GENRES.includes(genre));const visibleGenres=["all",...NEON_PRIMARY_GENRES,...otherGenres];if(!visibleGenres.includes(activeGenre))activeGenre="all";els.genreFilters.innerHTML=visibleGenres.map((genre,index)=>`<button class="chip ${index>NEON_PRIMARY_GENRES.length?"neon-secondary-genre ":""}${genre===activeGenre?"is-active":""}" type="button" data-genre="${esc(genre)}" aria-pressed="${genre===activeGenre}">${esc(genreName(genre))}</button>`).join("")}else{if(!available.includes(activeGenre))activeGenre="all";els.genreFilters.innerHTML=available.map(g=>`<button class="chip ${g===activeGenre?"is-active":""}" type="button" data-genre="${esc(g)}" aria-pressed="${g===activeGenre}">${esc(genreName(g))}</button>`).join("")}syncGenreAccent();updateGenreOverflow()}
let catalogAlignmentFrame;
function alignCatalogControls(){cancelAnimationFrame(catalogAlignmentFrame);catalogAlignmentFrame=requestAnimationFrame(()=>{const cards=[...els.filmGrid.children];if(!cards.length){els.catalogHeading.style.removeProperty("--catalog-right-inset");return}const gridRect=els.filmGrid.getBoundingClientRect(),firstTop=cards[0].getBoundingClientRect().top;const firstRow=cards.filter(card=>Math.abs(card.getBoundingClientRect().top-firstTop)<2);const rowRight=Math.max(...firstRow.map(card=>card.getBoundingClientRect().right));els.catalogHeading.style.setProperty("--catalog-right-inset",`${Math.max(0,gridRect.right-rowRight)}px`)})}
function renderCatalogMenu(){if(catalogPlaylistId!=="all"&&!playlists.some(item=>sameId(item.id,catalogPlaylistId))){catalogPlaylistId="all";saveCatalogState()}$("catalogPlaylistSelect").innerHTML='<option value="all">Alle Playlisten</option>'+playlists.map(item=>`<option value="${esc(item.id)}" ${sameId(item.id,catalogPlaylistId)?"selected":""}>${esc(item.name)}</option>`).join("");$("catalogSortSelect").value=catalogSort;$("catalogOriginalTitleToggle").checked=showCatalogOriginalTitles;renderCatalogLanguageFilters();renderCatalogSubtitleFilters()}
function directorShortName(name){const words=String(name||"").trim().split(/\s+/).filter(Boolean);return words.at(-1)||"Regie unbekannt"}
function compactDirectorNames(){els.filmGrid.querySelectorAll("[data-director-filter]").forEach(link=>{link.textContent=link.dataset.directorFilter;link.classList.remove("is-short");if(link.scrollWidth>link.clientWidth){link.textContent=directorShortName(link.dataset.directorFilter);link.classList.add("is-short")}})}
function filterByDirector(name){catalogSearchQuery=name;els.searchInput.value=name;saveCatalogState();renderCatalog();renderHero();els.searchInput.focus()}
function catalogDisplayTitle(film){const display=localizedFilm(film);return showCatalogOriginalTitles&&String(display.originalTitle||"").trim()?display.originalTitle:display.title}
function renderCatalog(){renderCatalogMenu();const films=filteredFilms();els.filmGrid.classList.toggle("is-searching",Boolean(els.searchInput.value.trim()));els.filmCount.textContent=`${films.length} ${films.length===1?"Titel":"Titel"}`;els.filmGrid.innerHTML=films.map(f=>{const collectionNumber=catalogSort==="collection-number"?filmCollectionNumber(f):"",director=String(f.director||"").trim();return `<article class="film-card"><button class="film-card-main" type="button" data-film-detail="${esc(f.id)}"><span class="poster" style="${posterStyle(f)}">${cover(f)}<span class="play-badge" aria-hidden="true">▶</span></span><span class="film-info"><strong>${esc(catalogDisplayTitle(f))}</strong></span></button><span class="film-meta"><span>${esc(f.year||"—")} ·</span>${director?`<button type="button" data-director-filter="${esc(director)}" title="Alle Filme von ${esc(director)}">${esc(director)}</button>`:`<span>Regie unbekannt</span>`}</span>${collectionNumber?`<small class="collection-number"># ${esc(collectionNumber)}</small>`:""}</article>`}).join("");els.filmGrid.querySelectorAll("[data-film-detail]").forEach(card=>card.addEventListener("click",()=>showDetail(card.dataset.filmDetail)));els.filmGrid.querySelectorAll("[data-director-filter]").forEach(link=>link.addEventListener("click",()=>filterByDirector(link.dataset.directorFilter)));els.emptyState.hidden=films.length>0;compactDirectorNames();alignCatalogControls()}
function setCatalogDrawer(open){$("catalogDrawer").classList.toggle("is-open",open);$("catalogBackdrop").classList.toggle("is-open",open);$("catalogDrawer").setAttribute("aria-hidden",String(!open));$("catalogMenuButton").setAttribute("aria-expanded",String(open));document.body.classList.toggle("catalog-drawer-open",open);if(open)setTimeout(()=>$("catalogDrawerClose").focus(),180)}
function renderHero(){}
function renderTable(){const p=activeProject(),films=p.films.filter(film=>filmMatchesQuery(film,els.searchInput.value));els.filmTableBody.innerHTML=films.length?films.map(f=>{const copies=filmCopies(f),primary=copies[0]||{},status=copies.some(copy=>copy.status==="verfügbar")?"verfügbar":copies.some(copy=>copy.status==="prüfen")?"prüfen":"nicht verfügbar";return `<tr><td><div class="title-cell film-drag-handle" draggable="true" data-drag-film-id="${esc(f.id)}" data-drag-project-id="${esc(p.id)}" title="${esc(f.title)} in ein anderes Projekt verschieben">${cover(f,true)}<strong>${esc(f.title)}</strong></div></td><td>${esc(f.year||"—")}</td><td>${esc(genreText(f.genre)||"—")}</td><td class="link-cell" title="${esc(primary.link||"")}">${copies.length?`${copies.length} ${copies.length===1?"Fassung":"Fassungen"}`:"Keine Fassung"}</td><td><span class="status" data-status="${esc(status)}">${status==="verfügbar"?"geprüft":esc(status)}</span></td><td><button class="row-menu" type="button" data-edit-film="${esc(f.id)}" aria-label="${esc(f.title)} bearbeiten">•••</button></td></tr>`}).join(""):`<tr><td colspan="6" class="muted">${p.films.length?"Keine passenden Filme gefunden.":"Noch keine Filme in diesem Projekt."}</td></tr>`}
function projectDropRow(target){return target.closest?.(".project-row")?.querySelector("[data-project-id]")?.closest(".project-row")||null}
function clearProjectDropTargets(){document.querySelectorAll(".project-row.is-film-drop-target").forEach(row=>row.classList.remove("is-film-drop-target"))}
function clearFilmDropState(){clearProjectDropTargets();document.querySelectorAll(".film-drag-handle.is-dragging").forEach(handle=>handle.classList.remove("is-dragging"))}
function startFilmDrag(event){const handle=event.target.closest("[data-drag-film-id]");if(!handle)return;draggedFilmReference={filmId:handle.dataset.dragFilmId,projectId:handle.dataset.dragProjectId};handle.classList.add("is-dragging");event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/plain",handle.dataset.dragFilmId);if(event.dataTransfer.setDragImage)event.dataTransfer.setDragImage(handle,24,24)}
function dragFilmOverProject(event){const row=projectDropRow(event.target),targetId=row?.querySelector("[data-project-id]")?.dataset.projectId;if(!draggedFilmReference||!targetId||sameId(targetId,draggedFilmReference.projectId))return;event.preventDefault();event.dataTransfer.dropEffect="move";clearProjectDropTargets();row.classList.add("is-film-drop-target")}
function leaveFilmProject(event){const row=projectDropRow(event.target);if(row&&!row.contains(event.relatedTarget))row.classList.remove("is-film-drop-target")}
function mergeFilmIntoProject(target,film){const identifiers=["tmdbId","imdbId","wikidataId"],hasId=identifiers.some(key=>String(film[key]||"").trim());if(!hasId){target.films.unshift(film);return film}const matches=target.films.filter(candidate=>identifiers.some(key=>film[key]&&candidate[key]&&String(film[key])===String(candidate[key])));if(!matches.length){target.films.unshift(film);return film}const base=matches[0],copiesByLink=new Map();[...filmCopies(base),...filmCopies(film)].forEach(copy=>{const link=String(copy.link||"").trim(),key=link||`missing-${copiesByLink.size}`;if(!copiesByLink.has(key))copiesByLink.set(key,{...copy})});base.copies=[...copiesByLink.values()];base.localizedMetadata={...(base.localizedMetadata||{}),...(film.localizedMetadata||{})};identifiers.forEach(key=>{if(!base[key]&&film[key])base[key]=film[key]});const protectedFields=new Set(["id","copies","link","status","localizedMetadata",...identifiers]);Object.keys(base).forEach(key=>{if(!protectedFields.has(key)&&base[key]&&film[key]&&String(base[key])!==String(film[key]))base[key]=""});target.films=target.films.filter(candidate=>candidate===base||!matches.includes(candidate));return base}
function dropFilmOnProject(event){const row=projectDropRow(event.target),targetId=row?.querySelector("[data-project-id]")?.dataset.projectId,reference=draggedFilmReference;event.preventDefault();clearFilmDropState();draggedFilmReference=null;if(!reference||!targetId||sameId(targetId,reference.projectId))return;const source=projects.find(project=>sameId(project.id,reference.projectId)),target=projects.find(project=>sameId(project.id,targetId)),filmIndex=source?.films.findIndex(film=>sameId(film.id,reference.filmId))??-1;if(!source||!target||filmIndex<0)return;const [film]=source.films.splice(filmIndex,1);mergeFilmIntoProject(target,film);save();render();toast(`„${film.title}“ nach „${target.name}“ verschoben`)}
function setView(view){if(view===currentView)return;if(currentView==="cinema"){catalogSearchQuery=els.searchInput.value;saveCatalogState()}else archiveSearchQuery=els.searchInput.value;currentView=view;document.documentElement.dataset.view=view;els.cinemaView.hidden=view!=="cinema";els.machineView.hidden=view!=="machine";document.querySelectorAll("[data-view]").forEach(b=>b.classList.toggle("is-active",b.dataset.view===view));if(view==="machine"){archiveSearchQuery="";els.searchInput.value="";els.searchInput.blur();setCatalogDrawer(false)}else els.searchInput.value=catalogSearchQuery;render();syncNeonHeader()}
function selectProject(id){if(currentView==="cinema"){if(id!=="all"&&!projects.some(p=>p.id===id))return;catalogProjectId=id;activeGenre="all";saveCatalogState();render();return}if(!projects.some(p=>p.id===id))return;activeProjectId=id;archiveSearchQuery="";els.searchInput.value="";save();render()}
function normalizeRuntime(value){if(value===""||value===null||value===undefined)return "";if(typeof value==="number"||/^\d+(?:\.\d+)?$/.test(String(value).trim())){const seconds=Math.round(Number(value)*60);const hours=Math.floor(seconds/3600);const minutes=Math.floor(seconds%3600/60);return `${hours}:${String(minutes).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`}const match=String(value).trim().match(/^(\d{1,3}):([0-5]\d):([0-5]\d)$/);return match?`${Number(match[1])}:${match[2]}:${match[3]}`:""}
function closeProjectRowMenus(){document.querySelectorAll("[data-project-row-popup],[data-playlist-row-popup]").forEach(menu=>{menu.hidden=true});document.querySelectorAll("[data-project-row-menu],[data-playlist-row-menu]").forEach(button=>button.setAttribute("aria-expanded","false"))}
function toggleProjectRowMenu(id){const menu=document.querySelector(`[data-project-row-popup="${CSS.escape(id)}"]`);const button=document.querySelector(`[data-project-row-menu="${CSS.escape(id)}"]`);if(!menu||!button)return;const willOpen=menu.hidden;closeProjectRowMenus();menu.hidden=!willOpen;button.setAttribute("aria-expanded",String(willOpen))}
function togglePlaylistRowMenu(id){const menu=document.querySelector(`[data-playlist-row-popup="${CSS.escape(id)}"]`);const button=document.querySelector(`[data-playlist-row-menu="${CSS.escape(id)}"]`);if(!menu||!button)return;const willOpen=menu.hidden;closeProjectRowMenus();menu.hidden=!willOpen;button.setAttribute("aria-expanded",String(willOpen))}
function editProjectField(id,field,label){const p=projects.find(x=>sameId(x.id,id));if(!p)return;const value=window.prompt(label,p[field]||"");if(value===null)return;p[field]=value.trim();save();render();toast("Projekt aktualisiert")}function deleteProject(id){const project=projects.find(item=>item.id===id);if(!project)return;if(projects.length===1){toast("Das letzte Projekt kann nicht gelöscht werden");return}projects=projects.filter(item=>item.id!==id);if(activeProjectId===id)activeProjectId=projects[0].id;if(catalogProjectId===id){catalogProjectId="all";activeGenre="all";saveCatalogState()}save();render();toast("Projekt gelöscht")}
let editingCopies=[];
let editingLocalizedMetadata={};
let editingPlaylistIds=new Set();
let editingPlaylistNumbers=new Map();
function filmCopies(film){if(Array.isArray(film?.copies))return film.copies.map(copy=>({...copy,title:copy.title||copy.label||"",access:["public","password"].includes(copy.access)?copy.access:"private",password:String(copy.password||"")}));return film?.link?[{id:uid("copy"),title:"Fassung 1",link:film.link,languages:"",resolution:"",quality:"",status:film.status||"verfügbar",access:"private",password:""}]:[]}
function setFilmTab(tab){const active=["general","copies","playlists"].includes(tab)?tab:"general";document.querySelectorAll("[data-film-tab]").forEach(button=>{const selected=button.dataset.filmTab===active;button.classList.toggle("is-active",selected);button.setAttribute("aria-selected",String(selected))});$("filmGeneralPanel").hidden=active!=="general";$("filmCopiesPanel").hidden=active!=="copies";$("filmPlaylistsPanel").hidden=active!=="playlists"}
function updateFilmPlaylistCount(){const checked=[$("filmPlaylistChecklist")].flatMap(root=>[...root.querySelectorAll('[data-playlist-check]:checked')]);$("filmPlaylistCount").textContent=checked.length}
function playlistNumber(playlist,filmId){return String((playlist.filmAssignments||[]).find(entry=>sameId(entry.filmId,filmId))?.collectionNumber||"")}
function renderFilmPlaylistChecklist(){$("filmPlaylistsEmpty").hidden=playlists.length>0;$("filmPlaylistChecklist").hidden=!playlists.length;$("filmPlaylistChecklist").innerHTML=playlists.map(playlist=>{const id=String(playlist.id),checked=editingPlaylistIds.has(id);return `<div class="film-playlist-option"><label class="playlist-check-main"><input data-playlist-check type="checkbox" value="${esc(id)}" ${checked?"checked":""}><span><strong>${esc(playlist.name)}</strong><small>${playlist.filmIds?.length||0} ${playlist.filmIds?.length===1?"Film":"Filme"}</small></span></label><label class="playlist-number-field"><span>Sammlungsnummer</span><input data-playlist-number maxlength="6" pattern="[A-Za-z0-9]{0,6}" inputmode="text" value="${esc(editingPlaylistNumbers.get(id)||"")}" placeholder="ABC123"></label></div>`}).join("");$("filmPlaylistChecklist").querySelectorAll("[data-playlist-check]").forEach(input=>input.addEventListener("change",updateFilmPlaylistCount));$("filmPlaylistChecklist").querySelectorAll("[data-playlist-number]").forEach(input=>input.addEventListener("input",()=>{input.value=input.value.replace(/[^A-Za-z0-9]/g,"").slice(0,6)}));updateFilmPlaylistCount()}
function readFilmPlaylistChecklist(){editingPlaylistIds=new Set();editingPlaylistNumbers=new Map();$("filmPlaylistChecklist").querySelectorAll(".film-playlist-option").forEach(row=>{const checkbox=row.querySelector("[data-playlist-check]"),number=row.querySelector("[data-playlist-number]").value.trim();if(checkbox.checked){editingPlaylistIds.add(String(checkbox.value));editingPlaylistNumbers.set(String(checkbox.value),number)}})}
function readCopyEditor(){editingCopies=[...$("filmCopiesList").querySelectorAll("[data-copy-id]")].map(row=>({id:row.dataset.copyId,title:row.querySelector('[data-copy-field="title"]').value.trim(),link:row.querySelector('[data-copy-field="link"]').value.trim(),access:row.querySelector('[data-copy-field="access"]').value,password:row.querySelector('[data-copy-field="password"]').value,languages:semanticLanguages(row.querySelector('[data-copy-field="languages"]').value),subtitles:semanticLanguages(row.querySelector('[data-copy-field="subtitles"]').value),resolution:row.querySelector('[data-copy-field="resolution"]').value,quality:row.querySelector('[data-copy-field="quality"]').value,status:row.querySelector('[data-copy-field="status"]').value}))}
function renderCopyEditor(){$("filmCopyCount").textContent=editingCopies.length;$("filmCopiesEmpty").hidden=editingCopies.length>0;$("filmCopiesList").innerHTML=editingCopies.map((copy,index)=>`<section class="film-copy" data-copy-id="${esc(copy.id)}"><div class="film-copy-head"><strong>Fassung ${index+1}</strong><button type="button" data-remove-copy="${esc(copy.id)}" aria-label="Fassung ${index+1} entfernen">Entfernen</button></div><div class="copy-grid"><label>Quelle<input data-copy-field="title" maxlength="160" value="${esc(copy.title||copy.label||"")}" placeholder="z. B. Deutsche Kinofassung"></label><label>Sprache(n)<input data-copy-field="languages" maxlength="120" value="${esc(languageText(copy.languages))}" list="languageOptions" placeholder="Deutsch, Englisch"></label><label>Untertitel<input data-copy-field="subtitles" maxlength="120" value="${esc(languageText(copy.subtitles))}" list="languageOptions" placeholder="Deutsch, Englisch, keine"></label><div class="copy-link-row span-2"><label>Link zum Film<input data-copy-field="link" type="url" value="${esc(copy.link||"")}" placeholder="https://… oder file:///…"></label><label>Zugriff<select data-copy-field="access"><option value="private" ${copy.access!=="public"&&copy.access!=="password"?"selected":""}>Privates Archiv · erworben</option><option value="public" ${copy.access==="public"?"selected":""}>Frei zugänglich</option><option value="password" ${copy.access==="password"?"selected":""}>Zugänglich mit Passwort</option></select></label></div><label class="copy-password-field span-2" ${copy.access==="password"?"":"hidden"}>Passwort<input data-copy-field="password" type="password" value="${esc(copy.password||"")}" autocomplete="off" placeholder="Passwort für den Link"></label><label>Auflösung<select data-copy-field="resolution"><option value="">Nicht angegeben</option>${["4K / UHD","1080p","720p","576p","480p","Andere"].map(value=>`<option ${copy.resolution===value?"selected":""}>${value}</option>`).join("")}</select></label><label>Qualität<select data-copy-field="quality"><option value="">Nicht bewertet</option>${["Hervorragend","Sehr gut","Gut","Akzeptabel","Schlecht"].map(value=>`<option ${copy.quality===value?"selected":""}>${value}</option>`).join("")}</select></label><label>Status<select data-copy-field="status"><option value="verfügbar" ${copy.status==="verfügbar"?"selected":""}>Verfügbar</option><option value="prüfen" ${copy.status==="prüfen"?"selected":""}>Link prüfen</option><option value="nicht verfügbar" ${copy.status==="nicht verfügbar"?"selected":""}>Nicht verfügbar</option></select><small class="status-availability-note">Die Verfügbarkeit kann je nach Anbieter zeitweise schwanken.</small></label></div></section>`).join("");$("filmCopiesList").querySelectorAll('[data-copy-field="access"]').forEach(select=>select.addEventListener("change",()=>{select.closest(".film-copy").querySelector(".copy-password-field").hidden=select.value!=="password"}));$("filmCopiesList").querySelectorAll("[data-remove-copy]").forEach(button=>button.addEventListener("click",()=>{readCopyEditor();editingCopies=editingCopies.filter(copy=>!sameId(copy.id,button.dataset.removeCopy));renderCopyEditor()}))}
function addFilmCopy(){readCopyEditor();editingCopies.push({id:uid("copy"),title:`Fassung ${editingCopies.length+1}`,link:"",access:"private",password:"",languages:"",subtitles:"",resolution:"",quality:"",status:"verfügbar"});renderCopyEditor();setFilmTab("copies")}
