let tmdbSearchResults=[];
const FILM_IDENTIFIER_FIELDS={tmdb:'filmTmdbId',imdb:'filmImdbId',wikidata:'filmWikidataId',tvdb:'filmTvdbId',eidr:'filmEidr',isan:'filmIsan',letterboxd:'filmLetterboxdId',rottenTomatoes:'filmRottenTomatoesId'};
function syncIdentifierFields(film={}){const values={filmTmdbId:film.tmdbId||"",filmImdbId:film.imdbId||"",filmWikidataId:film.wikidataId||"",filmTvdbId:film.tvdbId||"",filmEidr:film.eidr||"",filmIsan:film.isan||"",filmLetterboxdId:film.letterboxdId||"",filmRottenTomatoesId:film.rottenTomatoesId||""};Object.entries(values).forEach(([id,value])=>$(id).value=value);updateIdentifierStatuses()}
function readIdentifierData(){return{tmdbId:$('filmTmdbId').value.trim(),imdbId:$('filmImdbId').value.trim(),wikidataId:$('filmWikidataId').value.trim(),tvdbId:$('filmTvdbId').value.trim(),eidr:$('filmEidr').value.trim(),isan:$('filmIsan').value.trim(),letterboxdId:$('filmLetterboxdId').value.trim(),rottenTomatoesId:$('filmRottenTomatoesId').value.trim()}}
