function tmdbRuntime(minutes){const total=Math.max(0,Number(minutes)||0)*60;return `${Math.floor(total/3600)}:${String(Math.floor(total%3600/60)).padStart(2,"0")}:00`}
async function fetchTmdb(path,params={}){if(!tmdbToken)throw new Error("token-missing");const url=new URL(`${TMDB_API_URL}${path}`);Object.entries(params).forEach(([key,value])=>{if(value!==""&&value!==undefined&&value!==null)url.searchParams.set(key,String(value))});const response=await fetch(url,{headers:{Accept:"application/json",Authorization:`Bearer ${tmdbToken}`}});if(!response.ok)throw new Error(`tmdb-${response.status}`);return response.json()}
const wait=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));
async function syncFilmMetadata(){const locale=selectedFilmLocale();if(locale==="original"){toast("Für die Originalsprache ist keine Synchronisierung erforderlich");return}if(!tmdbToken){toast("Bitte zuerst den TMDB-Token hinterlegen");return}const films=projects.flatMap(project=>project.films).filter(film=>film.tmdbId&&!film.localizedMetadata?.[locale]),progress=$("filmMetadataSyncProgress"),bar=progress.querySelector("progress"),label=progress.querySelector("small"),button=$("syncFilmMetadataButton");progress.hidden=false;button.disabled=true;let completed=0,failed=0;for(const film of films){label.textContent=`${completed} / ${films.length}`;try{let details;try{details=await fetchTmdb(`/movie/${encodeURIComponent(film.tmdbId)}`,{language:locale,append_to_response:"images",include_image_language:`${locale.split("-")[0]},null`})}catch(error){if(error.message!=="tmdb-429")throw error;await wait(2500);details=await fetchTmdb(`/movie/${encodeURIComponent(film.tmdbId)}`,{language:locale})}film.localizedMetadata={...(film.localizedMetadata||{}),[locale]:{title:details.title||film.title,originalTitle:details.original_title||film.originalTitle,description:details.overview||"",genre:(details.genres||[]).map(item=>item.name).join(", "),countries:(details.production_countries||[]).map(item=>item.name).join(", "),cover:details.poster_path?`${TMDB_IMAGE_BASE_URL}/w500${details.poster_path}`:""}}}catch{failed++}completed++;bar.value=films.length?completed/films.length*100:100;label.textContent=`${completed} / ${films.length}`;save();await wait(150)}button.disabled=false;render();toast(films.length?`${completed-failed} Sprachvarianten synchronisiert${failed?`, ${failed} fehlgeschlagen`:""}`:"Alle Sprachvarianten sind bereits vorhanden")}
async function identifyExternalIds(silent=false){let tmdbId=$("filmTmdbId").value.trim(),wikidataId=$("filmWikidataId").value.trim();if(!tmdbId&&!wikidataId){if(!silent)$('tmdbStatus').textContent='Bitte zuerst eine TMDB- oder Wikidata-ID eintragen.';return}if(!silent)$('tmdbStatus').textContent='Externe IDs werden gesucht …';let found=false;try{if(tmdbId){const ids=await fetchTmdb(`/movie/${encodeURIComponent(tmdbId)}/external_ids`);[['filmImdbId',ids.imdb_id],['filmWikidataId',ids.wikidata_id],['filmTvdbId',ids.tvdb_id]].forEach(([id,value])=>{if(value)$(id).value=String(value)});wikidataId=$('filmWikidataId').value.trim();found=true}}catch{}if(wikidataId){try{const url=new URL('https://www.wikidata.org/w/api.php');url.search=new URLSearchParams({action:'wbgetentities',ids:wikidataId,props:'claims',format:'json',origin:'*'});const response=await fetch(url);if(!response.ok)throw new Error('Wikidata request failed');const entity=await response.json();const claims=entity?.entities?.[wikidataId]?.claims||{};const map={filmImdbId:'P345',filmTmdbId:'P4947',filmEidr:'P2704',filmIsan:'P1874',filmLetterboxdId:'P6127',filmRottenTomatoesId:'P1258'};Object.entries(map).forEach(([id,p])=>{const snak=(claims[p]||[]).find(c=>c.mainsnak?.datavalue);const v=snak?.mainsnak?.datavalue?.value;if(v!==undefined)$(id).value=String(typeof v==='object'?(v.id||v.text||''):v)});found=true}catch{}}updateIdentifierStatuses();if(!silent)$('tmdbStatus').textContent=found?'Verfügbare externe IDs wurden übernommen.':'Die externen IDs konnten nicht geladen werden.'}
function renderTmdbResults(results){tmdbSearchResults=results;$("tmdbResults").hidden=!results.length;$("tmdbResults").innerHTML=results.map((film,index)=>{const year=String(film.release_date||"").slice(0,4)||"—";const poster=film.poster_path?`<img src="${TMDB_IMAGE_BASE_URL}/w92${esc(film.poster_path)}" alt="">`:`<span class="tmdb-result-placeholder" aria-hidden="true"></span>`;return `<button type="button" class="tmdb-result" data-tmdb-result="${index}">${poster}<span><strong>${esc(film.title)}</strong><small>${esc(year)}${film.original_title&&film.original_title!==film.title?` · ${esc(film.original_title)}`:""}</small><em>${esc(film.overview||"Keine Beschreibung verfügbar.")}</em></span><b>Daten übernehmen</b></button>`}).join("");$("tmdbResults").querySelectorAll("[data-tmdb-result]").forEach(button=>button.addEventListener("click",()=>applyTmdbResult(tmdbSearchResults[Number(button.dataset.tmdbResult)])))}
async function searchTmdb(){const manualId=$("filmTmdbId").value.trim(),button=document.querySelector('[data-fetch-id="tmdb"]'),requested=selectedFilmLocale(),locale=requested==="original"?(interfaceLanguage()==="de"?"de-DE":"en-US"):requested;if(!tmdbToken){$("tmdbTokenRow").hidden=false;$("tmdbTokenInput").focus();$("tmdbStatus").textContent="Bitte zuerst einen TMDB API Read Access Token hinterlegen.";return}if(!manualId&&!$("filmTitle").value.trim()){$("tmdbStatus").textContent="Bitte zuerst einen Filmtitel oder eine TMDB-ID eingeben.";$("filmTitle").focus();return}if(button)button.disabled=true;$("tmdbStatus").textContent="TMDB wird durchsucht …";$("tmdbResults").hidden=true;try{const payload=manualId?{results:[await fetchTmdb(`/movie/${encodeURIComponent(manualId)}`,{language:locale})]}:await fetchTmdb("/search/movie",{query:$("filmTitle").value.trim(),language:locale,include_adult:"false",page:1});const results=(payload.results||[]).slice(0,8);renderTmdbResults(results);$("tmdbStatus").textContent=results.length?`${results.length} Treffer gefunden. Bitte den passenden Film auswählen.`:"Kein passender Film gefunden."}catch(error){$("tmdbStatus").textContent=error.message==="tmdb-401"?"Der TMDB-Token wurde nicht akzeptiert.":"TMDB konnte gerade nicht erreicht werden.";if(error.message==="tmdb-401")$("tmdbTokenRow").hidden=false}finally{if(button)button.disabled=false}}
function getGermanRating(details){const releases=(details.release_dates?.results||[]).find(item=>item.iso_3166_1==="DE")?.release_dates||[];const certification=releases.map(item=>String(item.certification||"").trim()).find(Boolean);return certification?`FSK ${certification.replace(/^FSK\s*/i,"")}`:""}
function getYoutubeTrailer(details){const videos=details.videos?.results||[];const trailer=videos.find(video=>video.site==="YouTube"&&video.type==="Trailer"&&video.official&&video.iso_639_1==="de")||videos.find(video=>video.site==="YouTube"&&video.type==="Trailer"&&video.official)||videos.find(video=>video.site==="YouTube"&&video.type==="Trailer");return trailer?.key?`https://www.youtube.com/watch?v=${encodeURIComponent(trailer.key)}`:""}
