function readTimemapTmdbToken(){return new Promise(resolve=>{if(!window.indexedDB){resolve("");return}const request=indexedDB.open("timemap-local-db",1);request.onerror=()=>resolve("");request.onupgradeneeded=()=>{request.transaction.abort();resolve("")};request.onsuccess=()=>{const db=request.result;if(!db.objectStoreNames.contains("appState")){db.close();resolve("");return}const transaction=db.transaction("appState","readonly");const getRequest=transaction.objectStore("appState").get("primary");getRequest.onerror=()=>{db.close();resolve("")};getRequest.onsuccess=()=>{const token=String(getRequest.result?.state?.tmdbApiToken||"").trim();db.close();resolve(token)}}})}
